'use client'

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/registry/bases/radix/veil/ui/accordion'
import { Card } from '@/registry/bases/radix/veil/ui/card'
import Link from 'next/link'
import { CreditCard, HelpCircle, Package } from 'lucide-react'

const faqCategories = [
    {
        title: 'Getting Started',
        icon: Package,
        items: [
            {
                id: 'gs-1',
                question: 'How do I create an account?',
                answer: 'Click "Sign Up" and follow the prompts. You can sign up with email or connect your Google account.',
            },
            {
                id: 'gs-2',
                question: 'Is there a free trial?',
                answer: 'Yes, we offer a 14-day free trial with full access to all features. No credit card required.',
            },
        ],
    },
    {
        title: 'Billing',
        icon: CreditCard,
        items: [
            {
                id: 'b-1',
                question: 'What payment methods do you accept?',
                answer: 'We accept all major credit cards, PayPal, and bank transfers for annual plans.',
            },
            {
                id: 'b-2',
                question: 'Can I get a refund?',
                answer: 'We offer a 30-day money-back guarantee. Contact support within 30 days for a full refund.',
            },
        ],
    },
    {
        title: 'Support',
        icon: HelpCircle,
        items: [
            {
                id: 's-1',
                question: 'How do I contact support?',
                answer: 'You can reach us via email, live chat, or through your account dashboard. We typically respond within 24 hours.',
            },
            {
                id: 's-2',
                question: 'Do you offer phone support?',
                answer: 'Phone support is available for Pro and Enterprise plans during business hours (9 AM - 6 PM EST).',
            },
        ],
    },
]

export default function FAQs() {
    return (
        <section className="bg-background @container py-24">
            <div className="mx-auto max-w-2xl px-6">
                <div className="text-center">
                    <h2 className="text-balance font-serif text-4xl font-medium">Help Center</h2>
                    <p className="text-muted-foreground mx-auto mt-4 max-w-md text-balance">Browse by category to find the answers you need.</p>
                </div>
                <div className="mt-12 space-y-3">
                    {faqCategories.map((category) => (
                        <Card
                            key={category.title}
                            variant="outline"
                            className="p-5"
                        >
                            <div className="mb-4 flex items-center gap-2">
                                <category.icon className="text-muted-foreground size-4" />
                                <h3 className="text-foreground font-medium">{category.title}</h3>
                            </div>
                            <Accordion
                                type="single"
                                collapsible
                            >
                                {category.items.map((item) => (
                                    <AccordionItem
                                        key={item.id}
                                        value={item.id}
                                        className="border-dashed last:border-b-0"
                                    >
                                        <AccordionTrigger className="cursor-pointer py-3 text-sm font-medium hover:no-underline">{item.question}</AccordionTrigger>
                                        <AccordionContent>
                                            <p className="text-muted-foreground pb-1 text-sm">{item.answer}</p>
                                        </AccordionContent>
                                    </AccordionItem>
                                ))}
                            </Accordion>
                        </Card>
                    ))}
                </div>
                <p className="text-muted-foreground mt-8 text-center text-sm">
                    Need more help?{' '}
                    <Link
                        href="#"
                        className="text-primary font-medium hover:underline"
                    >
                        Contact our team
                    </Link>
                </p>
            </div>
        </section>
    )
}

'use client'

import * as React from 'react'
import * as AccordionPrimitive from '@radix-ui/react-accordion'
import { ChevronDownIcon } from 'lucide-react'
import { cn } from '@/registry/core/lib/utils'

function Accordion({ ...props }: React.ComponentProps) {
    return (
        <AccordionPrimitive.Root
            data-slot="accordion"
            {...props}
        />
    )
}

function AccordionItem({ className, ...props }: React.ComponentProps) {
    return (
        <AccordionPrimitive.Item
            data-slot="accordion-item"
            className={cn('not-last:border-b', className)}
            {...props}
        />
    )
}

function AccordionTrigger({ className, children, ...props }: React.ComponentProps) {
    return (
        <AccordionPrimitive.Header className="flex">
            <AccordionPrimitive.Trigger
                data-slot="accordion-trigger"
                className={cn('focus-visible:border-ring focus-visible:ring-ring/50 flex flex-1 items-start justify-between gap-4 rounded-md py-4 text-left text-sm font-medium outline-none transition-all hover:underline focus-visible:ring-[3px] disabled:pointer-events-none disabled:opacity-50 [&[data-state=open]>svg]:rotate-180', className)}
                {...props}
            >
                {children}
                <ChevronDownIcon className="text-muted-foreground pointer-events-none size-4 shrink-0 translate-y-0.5 transition-transform duration-200" />
            </AccordionPrimitive.Trigger>
        </AccordionPrimitive.Header>
    )
}

function AccordionContent({ className, children, ...props }: React.ComponentProps) {
    return (
        <AccordionPrimitive.Content
            data-slot="accordion-content"
            className="data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down overflow-hidden text-sm"
            {...props}
        >
            <div className={cn('pb-4 pt-0', className)}>{children}</div>
        </AccordionPrimitive.Content>
    )
}

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent }

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/registry/core/lib/utils'

const cardVariants = cva('text-card-foreground rounded-2xl', {
    variants: {
        variant: {
            default: 'bg-card ring-1 ring-foreground/6.5 shadow-lg shadow-foreground/5 dark:shadow-black/10',
            soft: 'bg-muted',
            mixed: 'bg-muted border',
            outline: 'bg-card ring-1 ring-border',
        },
    },
    defaultVariants: {
        variant: 'default',
    },
})

export interface CardProps extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof cardVariants> {}

const Card = React.forwardRef<HTMLDivElement, CardProps>(({ className, variant, ...props }, ref) => (
    <div
        ref={ref}
        className={cn(cardVariants({ variant, className }))}
        {...props}
    />
))
Card.displayName = 'Card'

const CardHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('flex flex-col space-y-1.5 p-6', className)}
        {...props}
    />
))
CardHeader.displayName = 'CardHeader'

const CardTitle = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('font-semibold leading-none tracking-tight', className)}
        {...props}
    />
))
CardTitle.displayName = 'CardTitle'

const CardDescription = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('text-muted-foreground text-sm', className)}
        {...props}
    />
))
CardDescription.displayName = 'CardDescription'

const CardContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('p-6 pt-0', className)}
        {...props}
    />
))
CardContent.displayName = 'CardContent'

const CardFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
    <div
        ref={ref}
        className={cn('flex items-center p-6 pt-0', className)}
        {...props}
    />
))
CardFooter.displayName = 'CardFooter'

export { Card, CardHeader, CardFooter, CardTitle, CardDescription, CardContent }

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

